"use client";

import { useState } from "react";
import { 
  Activity, 
  Bed, 
  Droplet, 
  Pill, 
  ClipboardList, 
  AlertTriangle,
  Check
} from "lucide-react";

// Dummy data for the ward
const wardBeds = [
  { id: "W1-B01", patient: "John Smith", age: 65, status: "Occupied", condition: "Post-Op CABG", nextMed: "14:00 (Aspirin)" },
  { id: "W1-B02", patient: "Available", age: null, status: "Empty", condition: null, nextMed: null },
  { id: "W1-B03", patient: "Maria Garcia", age: 42, status: "Occupied", condition: "Pneumonia", nextMed: "13:30 (IV Antibiotics)" },
  { id: "W1-B04", patient: "James Wilson", age: 78, status: "Critical", condition: "Sepsis", nextMed: "12:00 (Vasopressors)" },
  { id: "W1-B05", patient: "Under Maintenance", age: null, status: "Maintenance", condition: null, nextMed: null },
];

export default function NurseDashboard() {
  const [selectedWard, setSelectedWard] = useState("General Ward A");

  return (
    <div className="max-w-7xl mx-auto space-y-6">
      {/* Header */}
      <div className="flex flex-col sm:flex-row justify-between items-start sm:items-center gap-4">
        <div>
          <h1 className="text-2xl font-bold text-slate-900">Nursing Station</h1>
          <p className="text-sm text-slate-500">Monitor bed occupancy, vitals, and medication schedules.</p>
        </div>
        <select 
          value={selectedWard}
          onChange={(e) => setSelectedWard(e.target.value)}
          className="px-4 py-2 bg-white border border-slate-200 rounded-lg text-sm font-medium text-slate-700 focus:outline-none focus:ring-2 focus:ring-brand-500 shadow-sm"
        >
          <option>General Ward A</option>
          <option>ICU - Level 1</option>
          <option>Maternity Wing</option>
          <option>Pediatrics</option>
        </select>
      </div>

      {/* Quick Action Bar */}
      <div className="grid grid-cols-2 md:grid-cols-4 gap-4">
        <button className="flex items-center justify-center p-3 bg-brand-50 text-brand-700 rounded-xl border border-brand-200 hover:bg-brand-100 transition-colors font-semibold text-sm">
          <Activity className="w-5 h-5 mr-2" /> Record Vitals
        </button>
        <button className="flex items-center justify-center p-3 bg-purple-50 text-purple-700 rounded-xl border border-purple-200 hover:bg-purple-100 transition-colors font-semibold text-sm">
          <Pill className="w-5 h-5 mr-2" /> Administer Meds
        </button>
        <button className="flex items-center justify-center p-3 bg-green-50 text-green-700 rounded-xl border border-green-200 hover:bg-green-100 transition-colors font-semibold text-sm">
          <ClipboardList className="w-5 h-5 mr-2" /> Shift Handover
        </button>
        <button className="flex items-center justify-center p-3 bg-red-50 text-red-700 rounded-xl border border-red-200 hover:bg-red-100 transition-colors font-semibold text-sm">
          <AlertTriangle className="w-5 h-5 mr-2" /> Emergency Code
        </button>
      </div>

      {/* Bed Grid */}
      <div className="bg-white border border-slate-200 rounded-xl shadow-sm p-6">
        <h2 className="text-lg font-bold text-slate-800 mb-4">{selectedWard} - Live Status</h2>
        
        <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 xl:grid-cols-5 gap-4">
          {wardBeds.map((bed) => (
            <div 
              key={bed.id} 
              className={`border rounded-lg p-4 transition-all ${
                bed.status === 'Occupied' ? 'border-brand-200 bg-brand-50/30' :
                bed.status === 'Critical' ? 'border-red-300 bg-red-50' :
                bed.status === 'Empty' ? 'border-slate-200 bg-slate-50 border-dashed' :
                'border-orange-200 bg-orange-50'
              }`}
            >
              <div className="flex justify-between items-start mb-3">
                <span className={`inline-flex items-center px-2 py-1 rounded text-xs font-bold ${
                  bed.status === 'Occupied' ? 'bg-brand-100 text-brand-700' :
                  bed.status === 'Critical' ? 'bg-red-100 text-red-700' :
                  bed.status === 'Empty' ? 'bg-slate-200 text-slate-600' :
                  'bg-orange-100 text-orange-700'
                }`}>
                  <Bed className="w-3 h-3 mr-1" />
                  {bed.id}
                </span>
                {bed.status === 'Critical' && <Activity className="w-4 h-4 text-red-500 animate-pulse" />}
              </div>

              {bed.status === 'Empty' || bed.status === 'Maintenance' ? (
                <div className="text-center py-4 text-slate-500 text-sm font-medium">
                  {bed.patient}
                </div>
              ) : (
                <div className="space-y-2">
                  <div>
                    <p className="font-bold text-slate-900 truncate" title={bed.patient}>{bed.patient}</p>
                    <p className="text-xs text-slate-500">{bed.age} yrs • {bed.condition}</p>
                  </div>
                  
                  <div className="pt-2 border-t border-slate-200/60 flex items-center justify-between">
                    <div className="flex items-center text-xs text-slate-600">
                      <Droplet className="w-3 h-3 mr-1 text-blue-500" />
                      {bed.nextMed}
                    </div>
                    <button className="p-1 rounded hover:bg-slate-200 text-slate-400 hover:text-brand-600 transition-colors" title="Mark Meds Given">
                      <Check className="w-4 h-4" />
                    </button>
                  </div>
                </div>
              )}
            </div>
          ))}
        </div>
      </div>
    </div>
  );
}